INSERT INTO products (slug, name, category_id, image_url, gallery_json, short_description, description, origin, packaging, moq, private_label, incoterms, certifications_json, needs_unique_image, featured, seo_title, seo_description) VALUES ('rice', 'Rice', 'agriculture', '/products/2-1.webp', '[]', 'Rice is one of the world\'s most important staple foods, and India is among the largest producers and exporters of premium rice varieties.', 'Rice is one of the world\'s most important staple foods, and India is among the largest producers and exporters of premium rice varieties. We supply Basmati and Non-Basmati rice sourced from Punjab, Haryana, Uttar Pradesh and West Bengal. Carefully processed, aged and packed under strict international food-safety standards for rich aroma, long grains and excellent taste. Packaging: 5 kg, 10 kg, 25 kg, 50 kg bags with private labelling. Min. order: 20–22 MT / 1 full truck / 1 full container. Backed by ISO, FSSAI and APEDA certifications. Highly demanded in the Middle East, Europe, Africa and Asia.', 'India (Punjab, Haryana, UP, West Bengal)', '5 kg, 10 kg, 25 kg, 50 kg bags', '20–22 MT (1 full truck / 1 FCL)', 1, 'FOB / CIF / CFR (TBC)', '["ISO 9001:2015","FSSAI","APEDA"]', 0, 1, 'Indian Basmati & Non-Basmati Rice Exporter | Mondal Export Import', 'ISO, FSSAI & APEDA certified Indian rice exporter supplying aged Basmati and Non-Basmati rice in 5-50 kg private label bags globally.') ON DUPLICATE KEY UPDATE name=VALUES(name), category_id=VALUES(category_id), image_url=VALUES(image_url), gallery_json=VALUES(gallery_json), short_description=VALUES(short_description), description=VALUES(description), origin=VALUES(origin), packaging=VALUES(packaging), moq=VALUES(moq), private_label=VALUES(private_label), incoterms=VALUES(incoterms), certifications_json=VALUES(certifications_json), needs_unique_image=VALUES(needs_unique_image), featured=VALUES(featured), seo_title=VALUES(seo_title), seo_description=VALUES(seo_description);
